import{_ as e,c as n,o,ae as a}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Button/Link","description":"Button/Link","frontmatter":{"title":"Button/Link","description":"Button/Link"},"headers":[],"relativePath":"guide/field-types/actionable-button-link.md","filePath":"guide/field-types/actionable-button-link.md"}'),i={name:"guide/field-types/actionable-button-link.md"};function l(r,t,s,u,d,h){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="button-link" tabindex="-1">Button/Link <a class="header-anchor" href="#button-link" aria-label="Permalink to &quot;Button/Link&quot;">​</a></h1><p>An actionable button or CTA in a data table leads the audience where you want them to be. The custom Button/Link data type in Ninja Tables makes it easier. You can decide the data type right from the start when you add a column to the table. From your dashboard, go to the <strong>Ninja Tables plugin → Tables</strong> (the table where you want to add Column) <strong>→ Add Column</strong>.</p><ul><li>A pop-up form will appear, and you will see the available <strong>Data Type</strong> here. You can choose from the various data type listed in the below screenshot.</li></ul><h2 id="button-and-linked-buttons-in-ninja-tables" tabindex="-1">Button and Linked Buttons in Ninja Tables <a class="header-anchor" href="#button-and-linked-buttons-in-ninja-tables" aria-label="Permalink to &quot;Button and Linked Buttons in Ninja Tables&quot;">​</a></h2><p>This allows you to add a button in a column, links can also be added if required.</p><ul><li>Go to the <strong>Data Type</strong> option and select the Button/Link type of the column. <img src="https://ninjatables.com/wp-content/uploads/2023/09/Actionable-button-in-Ninja-Tables-1024x672.png" alt="Actionable button in Ninja Tables"></li></ul><h3 id="button-text" tabindex="-1"><strong>Button Text</strong> <a class="header-anchor" href="#button-text" aria-label="Permalink to &quot;**Button Text**&quot;">​</a></h3><p>Text buttons are one of the key components for a good UI of a table. Texts on the button elaborate on the button&#39;s function. Button text is HTML supported.</p><ul><li>You can also choose <strong>Open Link in a new window</strong>, where the button URL will open in a new window.</li><li><strong>Make Button as rounded corner</strong> makes the button&#39;s corner rounded.</li><li>When the button is clicked after selecting** Make Force download**, the file will be downloaded immediately.</li></ul><h3 id="button-style" tabindex="-1"><strong>Button Style</strong> <a class="header-anchor" href="#button-style" aria-label="Permalink to &quot;**Button Style**&quot;">​</a></h3><p>The button can be styled by customizing the background, text, and border colors. As you can see from the image above, we&#39;ve colored the button blue with white text and black border.</p><h3 id="link-with-rel-attribute" tabindex="-1"><strong>Link With Rel Attribute</strong> <a class="header-anchor" href="#link-with-rel-attribute" aria-label="Permalink to &quot;**Link With Rel Attribute**&quot;">​</a></h3><p>There are three types of rel attributes available, and you can select any of them based on your needs.</p><ul><li><strong>sponsored</strong>: A sponsored link is an advertisement that is displayed on the search engine results page after a user searches for certain keywords.</li><li><strong>nofollow:</strong> The nofollow tag tells search engines to ignore that link. Because nofollow links do not pass PageRank they likely don&#39;t impact search engine rankings.</li><li><strong>noreferrer:</strong> The rel=”noreferrer” tag is a special HTML attribute that can be added to a link tag (). It prevents passing the referrer information to the target website by removing the referral info from the HTTP header. Here&#39;s how the table looks with custom actionable buttons. <img src="https://ninjatables.com/wp-content/uploads/2023/09/buttons-in-columns-1024x384.png" alt="buttons in columns"> Add an actionable button or linked buttons to make your data table more dynamic and engagable.</li></ul>',14)])])}const p=e(i,[["render",l]]);export{c as __pageData,p as default};
